/// A change to an ordered list (room list, timeline), mirroring `eyeball_im::VectorDiff` with
/// plain values so apps can apply it to their own list type.
public enum ListDiff<T: Codable & Hashable & Sendable>: Codable, Hashable, Sendable {
    public struct Append: Codable, Hashable, Sendable {
        public var values: [T]

        public init(values: [T]) {
            self.values = values
        }
    }
    public struct PushFront: Codable, Hashable, Sendable {
        public var value: T

        public init(value: T) {
            self.value = value
        }
    }
    public struct PushBack: Codable, Hashable, Sendable {
        public var value: T

        public init(value: T) {
            self.value = value
        }
    }
    public struct Insert: Codable, Hashable, Sendable {
        public var index: Int
        public var value: T

        public init(index: Int, value: T) {
            self.index = index
            self.value = value
        }
    }
    public struct Set: Codable, Hashable, Sendable {
        public var index: Int
        public var value: T

        public init(index: Int, value: T) {
            self.index = index
            self.value = value
        }
    }
    public struct Remove: Codable, Hashable, Sendable {
        public var index: Int

        public init(index: Int) {
            self.index = index
        }
    }
    public struct Truncate: Codable, Hashable, Sendable {
        public var length: Int

        public init(length: Int) {
            self.length = length
        }
    }
    public struct Reset: Codable, Hashable, Sendable {
        public var values: [T]

        public init(values: [T]) {
            self.values = values
        }
    }
    case append(Append)
    case clear
    case pushFront(PushFront)
    case pushBack(PushBack)
    case popFront
    case popBack
    case insert(Insert)
    case set(Set)
    case remove(Remove)
    case truncate(Truncate)
    case reset(Reset)

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: AnyKey.self)
        switch try container.decode(String.self, forKey: AnyKey("op")) {
        case "append": self = .append(try Append(from: decoder))
        case "clear": self = .clear
        case "pushFront": self = .pushFront(try PushFront(from: decoder))
        case "pushBack": self = .pushBack(try PushBack(from: decoder))
        case "popFront": self = .popFront
        case "popBack": self = .popBack
        case "insert": self = .insert(try Insert(from: decoder))
        case "set": self = .set(try Set(from: decoder))
        case "remove": self = .remove(try Remove(from: decoder))
        case "truncate": self = .truncate(try Truncate(from: decoder))
        case "reset": self = .reset(try Reset(from: decoder))
        case let other: throw DecodingError.dataCorruptedError(forKey: AnyKey("op"), in: container, debugDescription: "Unknown ListDiff \(other)")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: AnyKey.self)
        switch self {
        case .append(let value):
            try container.encode("append", forKey: AnyKey("op"))
            try value.encode(to: encoder)
        case .clear:
            try container.encode("clear", forKey: AnyKey("op"))
        case .pushFront(let value):
            try container.encode("pushFront", forKey: AnyKey("op"))
            try value.encode(to: encoder)
        case .pushBack(let value):
            try container.encode("pushBack", forKey: AnyKey("op"))
            try value.encode(to: encoder)
        case .popFront:
            try container.encode("popFront", forKey: AnyKey("op"))
        case .popBack:
            try container.encode("popBack", forKey: AnyKey("op"))
        case .insert(let value):
            try container.encode("insert", forKey: AnyKey("op"))
            try value.encode(to: encoder)
        case .set(let value):
            try container.encode("set", forKey: AnyKey("op"))
            try value.encode(to: encoder)
        case .remove(let value):
            try container.encode("remove", forKey: AnyKey("op"))
            try value.encode(to: encoder)
        case .truncate(let value):
            try container.encode("truncate", forKey: AnyKey("op"))
            try value.encode(to: encoder)
        case .reset(let value):
            try container.encode("reset", forKey: AnyKey("op"))
            try value.encode(to: encoder)
        }
    }
}

