/// Something that changed about the signed-in session
public enum SessionEvent: Codable, Hashable, Sendable {
    public struct Refreshed: Codable, Hashable, Sendable {
        public var session: Session

        public init(session: Session) {
            self.session = session
        }
    }
    public struct Invalid: Codable, Hashable, Sendable {
        public var softLogout: Bool

        public init(softLogout: Bool) {
            self.softLogout = softLogout
        }
    }
    /// Tokens were refreshed: store the new session
    case refreshed(Refreshed)
    /// The server no longer accepts the session (signed out elsewhere)
    case invalid(Invalid)

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: AnyKey.self)
        switch try container.decode(String.self, forKey: AnyKey("type")) {
        case "refreshed": self = .refreshed(try Refreshed(from: decoder))
        case "invalid": self = .invalid(try Invalid(from: decoder))
        case let other: throw DecodingError.dataCorruptedError(forKey: AnyKey("type"), in: container, debugDescription: "Unknown SessionEvent \(other)")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: AnyKey.self)
        switch self {
        case .refreshed(let value):
            try container.encode("refreshed", forKey: AnyKey("type"))
            try value.encode(to: encoder)
        case .invalid(let value):
            try container.encode("invalid", forKey: AnyKey("type"))
            try value.encode(to: encoder)
        }
    }
}

